Method.Implementation:
Set %response.ContentType = "application/json; charset=UTF-8"
Set %response.CharSet    = "UTF-8"

Set raw  = %request.Content.Read()
Set data = {}.%FromJSON(raw)

If '$isobject(data) {
  Set %response.Status = 400
  Write {"success": false, "message": "请求体为空或 JSON 格式错误"}.%ToJSON()
  Quit $$$OK
}

// 必填字段校验 — 使用 %Get() 替代点号访问，避免 <UNDEFINED>
Set assessDate = data.%Get("assessment_date", "")
If assessDate = "" {
  Set %response.Status = 400
  Write {"success": false, "message": "缺少评估日期"}.%ToJSON()
  Quit $$$OK
}

Set patientName = data.%Get("patient_name", "")
If patientName = "" {
  Set %response.Status = 400
  Write {"success": false, "message": "缺少患者姓名"}.%ToJSON()
  Quit $$$OK
}

// 创建持久化对象
Set rec = ##class(ApacheII.Model.Assessment).%New()

// —— 患者信息 ——
Set rec.PatientName     = $zcvt(data.%Get("patient_name",""),"I","UTF8")
Set rec.AdmissionNo     = $zcvt(data.%Get("admission_no",""),"I","UTF8")
Set rec.BedNo           = $zcvt(data.%Get("bed_no",""),"I","UTF8")
Set rec.AssessmentDate  = $zdateh(assessDate, 3)

// —— 12 项生理指标 ——
If data.%IsDefined("temperature")       { Set rec.Temperature       = data.%Get("temperature") }
If data.%IsDefined("temp_score")        { Set rec.TempScore         = data.%Get("temp_score") }
If data.%IsDefined("map")               { Set rec.MAP               = data.%Get("map") }
If data.%IsDefined("map_score")         { Set rec.MAPScore          = data.%Get("map_score") }
If data.%IsDefined("heart_rate")        { Set rec.HeartRate         = data.%Get("heart_rate") }
If data.%IsDefined("hr_score")          { Set rec.HRScore           = data.%Get("hr_score") }
If data.%IsDefined("respiratory_rate")  { Set rec.RespiratoryRate   = data.%Get("respiratory_rate") }
If data.%IsDefined("rr_score")          { Set rec.RRScore           = data.%Get("rr_score") }
If data.%IsDefined("fio2_mode")         { Set rec.FiO2Mode          = data.%Get("fio2_mode") }
If data.%IsDefined("pao2")              { Set rec.PaO2              = data.%Get("pao2") }
If data.%IsDefined("aado2")             { Set rec.AaDO2             = data.%Get("aado2") }
If data.%IsDefined("oxy_score")         { Set rec.OxyScore          = data.%Get("oxy_score") }
If data.%IsDefined("arterial_ph")       { Set rec.ArterialpH        = data.%Get("arterial_ph") }
If data.%IsDefined("ph_score")          { Set rec.pHScore           = data.%Get("ph_score") }
If data.%IsDefined("serum_sodium")      { Set rec.SerumSodium       = data.%Get("serum_sodium") }
If data.%IsDefined("sodium_score")      { Set rec.SodiumScore       = data.%Get("sodium_score") }
If data.%IsDefined("serum_potassium")   { Set rec.SerumPotassium    = data.%Get("serum_potassium") }
If data.%IsDefined("potassium_score")   { Set rec.PotassiumScore    = data.%Get("potassium_score") }
If data.%IsDefined("serum_creatinine")  { Set rec.SerumCreatinine   = data.%Get("serum_creatinine") }
If data.%IsDefined("creatinine_score")  { Set rec.CreatinineScore   = data.%Get("creatinine_score") }
If data.%IsDefined("acute_renal_failure") { Set rec.AcuteRenalFailure = data.%Get("acute_renal_failure") }
If data.%IsDefined("hematocrit")        { Set rec.Hematocrit        = data.%Get("hematocrit") }
If data.%IsDefined("hct_score")         { Set rec.HCTScore          = data.%Get("hct_score") }
If data.%IsDefined("wbc")               { Set rec.WBC               = data.%Get("wbc") }
If data.%IsDefined("wbc_score")         { Set rec.WBCScore          = data.%Get("wbc_score") }
If data.%IsDefined("gcs")               { Set rec.GCS               = data.%Get("gcs") }
If data.%IsDefined("gcs_score")         { Set rec.GCSScore          = data.%Get("gcs_score") }

// —— 年龄 & 慢性健康 ——
If data.%IsDefined("age_group")         { Set rec.AgeGroup          = $zcvt(data.%Get("age_group"),"I","UTF8") }
If data.%IsDefined("age_score")         { Set rec.AgeScore          = data.%Get("age_score") }
If data.%IsDefined("chronic_health")    { Set rec.ChronicHealth     = $zcvt(data.%Get("chronic_health"),"I","UTF8") }
If data.%IsDefined("chronic_score")     { Set rec.ChronicScore      = data.%Get("chronic_score") }

// —— 汇总 ——
If data.%IsDefined("total_score")       { Set rec.TotalScore        = data.%Get("total_score") }
If data.%IsDefined("mortality_estimate") { Set rec.MortalityEstimate = data.%Get("mortality_estimate") }

// 保存到 IRIS 数据库
Set sc = rec.%Save()
If $$$ISERR(sc) {
  Set %response.Status = 500
  Set msg = $system.Status.GetErrorText(sc)
  Write {"success": false, "message": ("保存失败: "_msg)}.%ToJSON()
  Quit $$$OK
}

Set id    = rec.%Id()
Set score = rec.TotalScore
Write {
  "success":    true,
  "message":    ("已保存 — 患者: "_rec.PatientName_" | 总分: "_score_" | ID: "_id),
  "record_id":  (id)
}.%ToJSON()

Quit $$$OK

Set %response.ContentType = "application/json; charset=UTF-8" Set %response.CharSet = "UTF-8"
Set sql = "SELECT ID, PatientName, AdmissionNo, BedNo, " _ "AssessmentDate, TotalScore, MortalityEstimate, CreatedAt " _ "FROM ApacheII_Model.Assessment " _ "ORDER BY AssessmentDate DESC, ID DESC"
Set rs = ##class(%SQL.Statement).%ExecDirect(, sql) If rs.%SQLCODE < 0 { Set %response.Status = 500 Write {"success": false, "message": ("查询失败: "_rs.%Message)}.%ToJSON() Quit $$$OK }
Set list = [] While rs.%Next() { Set item = { "id": (rs.%Get("ID")), "patient_name": (rs.%Get("PatientName")), "admission_no": (rs.%Get("AdmissionNo")), "bed_no": (rs.%Get("BedNo")), "date": ($zdate(rs.%Get("AssessmentDate"), 3)), "total_score": (rs.%Get("TotalScore")), "mortality": (rs.%Get("MortalityEstimate")), "created_at": (rs.%Get("CreatedAt")) } Do list.%Push(item) }
Write { "success": true, "count": (list.%Size()), "records": (list) }.%ToJSON()
Quit $$$OK

Set %response.ContentType = "application/json; charset=UTF-8"
Set %response.CharSet    = "UTF-8"

Set admissionNo = %request.Get("admission_no", "")
Set patientName = %request.Get("patient_name", "")

If (admissionNo = "") && (patientName = "") {
  Set %response.Status = 400
  Write {"success": false, "message": "请提供住院号或患者姓名"}.%ToJSON()
  Quit $$$OK
}

// 计算近 30 天的 Horolog 起始日期
Set today = $h
Set thirtyDaysAgo = today - 30

// 构建 WHERE 子句
Set whereClause = " WHERE AssessmentDate >= " _ thirtyDaysAgo
If admissionNo '= "" {
  Set safeAdm = $replace(admissionNo, "'", "''")
  Set whereClause = whereClause _ " AND AdmissionNo LIKE '%" _ safeAdm _ "%'"
}
If patientName '= "" {
  Set safeName = $replace(patientName, "'", "''")
  Set whereClause = whereClause _ " AND PatientName LIKE '%" _ safeName _ "%'"
}

// 按日期倒序 + 创建时间倒序：同一天第一条 = 当天最新
Set sql = "SELECT AssessmentDate, MortalityEstimate "
        _ "FROM ApacheII_Model.Assessment"
        _ whereClause
        _ " ORDER BY AssessmentDate DESC, CreatedAt DESC"

Set rs = ##class(%SQL.Statement).%ExecDirect(, sql)
If rs.%SQLCODE < 0 {
  Set %response.Status = 500
  Write {"success": false, "message": ("查询失败: "_rs.%Message)}.%ToJSON()
  Quit $$$OK
}

// 遍历并去重：同一天只保留第一条（CreatedAt 最新）
Set result = []
Set seenDates = ""

While rs.%Next() {
  Set d = $zdate(rs.%Get("AssessmentDate"), 3)
  // 已见过此日期则跳过（SQL 按 CreatedAt DESC，第一条即最新）
  If seenDates [ ("|"_d_"|") { Continue }
  Set seenDates = seenDates _ "|" _ d _ "|"

  Set mortality = rs.%Get("MortalityEstimate")
  If mortality = "" { Set mortality = "null" }

  Set item = {
    "date":      (d),
    "mortality": (mortality)
  }
  Do result.%Push(item)
}

// 反转为时间正序（前端折线图从左到右按时间递增）
Set ordered = []
For i = result.%Size() - 1:-1:0 {
  Do ordered.%Push(result.%Get(i))
}

Write {
  "success": true,
  "count":   (ordered.%Size()),
  "data":    (ordered)
}.%ToJSON()

Quit $$$OK

// 设置 CSV 下载响应头
Set %response.ContentType = "text/csv; charset=UTF-8"
Set %response.CharSet    = "UTF-8"
Do %response.SetHeader("Content-Disposition",
  "attachment; filename=""ApacheII_export_"_$zdate($h,3)_".csv""")

// 读取筛选参数
Set startDate   = %request.Get("start_date", "")
Set endDate     = %request.Get("end_date", "")
Set admissionNo = %request.Get("admission_no", "")
Set patientName = %request.Get("patient_name", "")

// 构建 WHERE
Set whereParts = ""
If startDate '= "" {
  Set whereParts = whereParts _ " AND AssessmentDate >= " _ $zdateh(startDate, 3)
}
If endDate '= "" {
  Set whereParts = whereParts _ " AND AssessmentDate <= " _ $zdateh(endDate, 3)
}
If admissionNo '= "" {
  Set safeAdm = $replace(admissionNo, "'", "''")
  Set whereParts = whereParts _ " AND AdmissionNo LIKE '%" _ safeAdm _ "%'"
}
If patientName '= "" {
  Set safeName = $replace(patientName, "'", "''")
  Set whereParts = whereParts _ " AND PatientName LIKE '%" _ safeName _ "%'"
}
Set whereClause = ""
If whereParts '= "" { Set whereClause = " WHERE " _ $extract(whereParts, 6, *) }

// 查询全部数据
Set cols = "AssessmentDate,PatientName,AdmissionNo,BedNo,"
         _ "Temperature,TempScore,MAP,MAPScore,HeartRate,HRScore,"
         _ "RespiratoryRate,RRScore,FiO2Mode,PaO2,AaDO2,OxyScore,"
         _ "ArterialpH,pHScore,SerumSodium,SodiumScore,SerumPotassium,"
         _ "PotassiumScore,SerumCreatinine,CreatinineScore,AcuteRenalFailure,"
         _ "Hematocrit,HCTScore,WBC,WBCScore,GCS,GCSScore,"
         _ "AgeGroup,AgeScore,ChronicHealth,ChronicScore,"
         _ "TotalScore,MortalityEstimate,CreatedAt"
Set sql = "SELECT " _ cols _ " FROM ApacheII_Model.Assessment"
        _ whereClause _ " ORDER BY AssessmentDate DESC, ID DESC"

Set rs = ##class(%SQL.Statement).%ExecDirect(, sql)
If rs.%SQLCODE < 0 {
  Set %response.ContentType = "text/plain; charset=UTF-8"
  Write "查询失败: ", rs.%Message
  Quit $$$OK
}

// 输出 UTF-8 BOM（Excel 识别中文必需）
Write $char(239,187,191)

// CSV 表头
Write "评估日期,患者姓名,住院号,床号,"
Write "体温,体温评分,MAP,MAP评分,心率,心率评分,"
Write "呼吸频率,呼吸评分,氧合模式,PaO2,AaDO2,氧合评分,"
Write "动脉血pH,pH评分,血清钠,血清钠评分,血清钾,血清钾评分,"
Write "血清肌酐,肌酐评分,急性肾衰竭,红细胞比容,HCT评分,"
Write "WBC,WBC评分,GCS,GCS评分,年龄分组,年龄评分,"
Write "慢性健康,慢性评分,总分,预估死亡率,创建时间", !

// 逐行输出
While rs.%Next() {
  // 评估日期
  Set d = rs.%Get("AssessmentDate")
  If d '= "" { Write $zdate(d, 3) }
  Write ","

  // 患者信息（含逗号或引号时加引号转义）
  For col = "PatientName","AdmissionNo","BedNo" {
    Set v = rs.%Get(col)
    If v '= "" {
      Set v = $replace(v, """", """""")
      If (v [ ",") || (v [ """") || (v [ $c(10)) { Write """", v, """" }
      Else { Write v }
    }
    Write ","
  }

  // 数值字段
  Set numCols = $listbuild(
    "Temperature","TempScore","MAP","MAPScore",
    "HeartRate","HRScore","RespiratoryRate","RRScore",
    "PaO2","AaDO2","OxyScore",
    "ArterialpH","pHScore","SerumSodium","SodiumScore",
    "SerumPotassium","PotassiumScore","SerumCreatinine","CreatinineScore",
    "Hematocrit","HCTScore","WBC","WBCScore","GCS","GCSScore",
    "AgeScore","ChronicScore","TotalScore","MortalityEstimate")

  For i = 1:1:$listlength(numCols) {
    Set v = rs.%Get($list(numCols, i))
    If v '= "" { Write v }
    Write ","
  }

  // 氧合模式
  Set v = rs.%Get("FiO2Mode")
  If v = "low"  { Write "FiO2 < 0.5" }
  ElseIf v = "high" { Write "FiO2 >= 0.5" }
  Write ","

  // 急性肾衰竭
  Set v = rs.%Get("AcuteRenalFailure")
  If v = "Y" { Write "是" } ElseIf v = "N" { Write "否" }
  Write ","

  // 年龄分组 / 慢性健康
  For col = "AgeGroup","ChronicHealth" {
    Set v = rs.%Get(col)
    If v '= "" {
      Set v = $replace(v, """", """""")
      If (v [ ",") || (v [ """") { Write """", v, """" }
      Else { Write v }
    }
    Write ","
  }

  // 创建时间
  Set v = rs.%Get("CreatedAt")
  If v '= "" { Write $extract(v, 1, 19) }
  Write !
}

Quit $$$OK
